/**
 * UnifiedTable Component Type Definitions
 *
 * Comprehensive TypeScript interfaces and types for the UnifiedTable component,
 * which consolidates fragmented table functionality across DocBits.
 *
 * This ensures type-safe table implementations across all pages.
 */

// ============================================================================
// FEATURE TOGGLES
// ============================================================================

/**
 * Controls which table features are enabled/disabled
 */
export interface TableFeatures {
  /** Enable/disable sort arrows in column headers */
  sorting?: boolean;

  /** Enable/disable filter UI integration (inherited from parent) */
  filtering?: boolean;

  /** Enable/disable row selection (master + individual checkboxes) */
  selection?: boolean;

  /** Enable/disable bulk actions FAB menu */
  bulkActions?: boolean;

  /** Enable/disable per-row action dropdown menu */
  rowActions?: boolean;

  /** Enable/disable column resizing with persistence */
  resizable?: boolean;

  /** Enable/disable pagination controls */
  pagination?: boolean;

  /** Enable/disable column reordering via drag-drop */
  columnReorder?: boolean;

  /** Enable/disable column settings feature (show/hide columns) */
  columnSettings?: boolean;

  /** Enable/disable sticky first column (stays visible when scrolling horizontally) */
  stickyFirstColumn?: boolean;

  /** Enable/disable sticky last column (stays visible when scrolling horizontally) */
  stickyLastColumn?: boolean;

  /** Enable built-in client-side sorting (no need to handle sorting in parent component) */
  clientSideSort?: boolean;

  /** Enable built-in client-side filtering (filters rows locally instead of server-side) */
  clientSideFilter?: boolean;

  /** Enable built-in client-side pagination (paginate rows locally instead of server-side) */
  clientSidePagination?: boolean;

  /** Enable expandable rows: clicking a row toggles a full-width detail row
   *  rendered via the `row-detail` slot. Cell slots receive an `expanded`
   *  scope prop so the parent can render an expand indicator. */
  expandable?: boolean;
}

// ============================================================================
// COLUMN FILTERING
// ============================================================================

/**
 * Filter operators for text columns
 */
export type TextFilterOperator = 'contains' | 'exact' | 'starts_with' | 'ends_with' | 'smart';

/**
 * Filter operators for date columns
 */
export type DateFilterOperator = 'equal' | 'before' | 'after';

/**
 * All available filter operators
 */
export type FilterOperator = TextFilterOperator | DateFilterOperator;

/**
 * Column filter type - determines UI and available operators
 */
export type ColumnFilterType = 'text' | 'date' | 'number' | 'select';

/**
 * Single filter value with column, operator, and value
 */
export interface ColumnFilterValue {
  /** Column name being filtered */
  column: string;
  /** Filter operator */
  operator: FilterOperator;
  /** Filter value */
  value: string | number;
}

/**
 * Column filter configuration
 */
export interface ColumnFilterConfig {
  /** Filter type - determines input UI and operators */
  type?: ColumnFilterType;
  /** Override available operators */
  operators?: FilterOperator[];
  /** For 'select' type: dropdown options */
  options?: Array<{ label: string; value: string | number }>;
  /** Whether column is filterable (default: true) */
  filterable?: boolean;
}

/**
 * Filter change event payload emitted when filters change
 */
export interface FilterChangePayload {
  /** Array of active filter values */
  filters: ColumnFilterValue[];
  /** JSON string ready for API: { filters: [...], match_all: false } */
  filterJson: string;
  /** Whether all filters must match (AND) or any (OR) */
  matchAll: boolean;
}

// ============================================================================
// COLUMN DEFINITIONS
// ============================================================================

/**
 * Extended Quasar column definition with UnifiedTable-specific options
 */
export interface UnifiedTableColumn {
  /** Unique column identifier */
  name: string;

  /** Display label shown in header */
  label: string;

  /** Field accessor - string path or function */
  field: string | ((row: any) => any);

  /** Text alignment */
  align?: 'left' | 'center' | 'right';

  /** Can this column be sorted (show sort arrows) */
  sortable?: boolean;

  /** Can this column be reordered by drag-drop (default: true) */
  draggable?: boolean;

  /** Column width (px or %) */
  width?: string;

  /** Custom CSS for column cells */
  style?: string;

  /** Custom CSS classes for column cells */
  classes?: string;

  /** Custom CSS for column header */
  headerStyle?: string;

  /** Custom CSS classes for column header */
  headerClasses?: string;

  /** Override the column name used for sorting */
  sortBy?: string;

  /** Prevent text truncation for this column */
  noTruncate?: boolean;

  /**
   * Transform the raw cell value into a display string for client-side filtering.
   * When provided, text filters match against this formatted value instead of the raw data.
   * Useful for dates, enums, or any column where the displayed text differs from the stored value.
   */
  filterValue?: (value: any, row: any) => string;

  /**
   * Transform the raw cell value into its displayed string (QTable `format`).
   * Spread straight onto the underlying QTable column, so the default cell
   * renderer shows the formatted value without needing a per-column slot.
   * Used for data-driven date formatting on the dashboard (DOCB-12248).
   */
  format?: (value: any, row: any) => string;

  /**
   * Column filter configuration
   * - true: enable filtering with default text type
   * - false: disable filtering
   * - ColumnFilterConfig: custom filter configuration
   */
  filter?: boolean | ColumnFilterConfig;
}

// ============================================================================
// PAGINATION (includes sort state for QTable compatibility)
// ============================================================================

/**
 * Combined pagination and sort state
 * Bundled together because QTable expects sortBy/descending in the pagination object
 * Tables that only need sorting can omit the pagination fields (page, rowsPerPage, rowsNumber)
 */
export interface TablePaginationState {
  /** Current sort column name (null = no sort) */
  sortBy?: string | null;

  /** Sort direction: true = descending, false = ascending */
  descending?: boolean;

  /** Current page (1-indexed) - optional for sort-only tables */
  page?: number;

  /** Rows per page - optional for sort-only tables */
  rowsPerPage?: number;

  /** Total row count (for server-side pagination) - optional for sort-only tables */
  rowsNumber?: number;
}

/**
 * Sort direction enum for type safety
 */
export type SortDirection = 'asc' | 'desc';

// ============================================================================
// EVENT PAYLOADS
// ============================================================================

/**
 * Emitted when column sorting changes
 */
export interface SortEventPayload {
  column: string;
  direction: SortDirection;
}

/**
 * Emitted when row selection changes
 */
export interface SelectionChangePayload {
  selectedIds: string[];
  selectedRows: any[];
  totalSelected: number;
  totalAvailable: number;
}

/**
 * Emitted when bulk action is triggered
 */
export interface BulkActionPayload {
  action: 'export' | 'delete' | 'copy-ids';
  selectedIds: string[];
  selectedCount: number;
}

/**
 * Configuration for a single row action menu item
 */
export interface RowActionItem {
  /** Unique action identifier (emitted on click) */
  key: string;

  /** Display label for the action */
  label: string;

  /** Material icon name (optional) */
  icon?: string;

  /** Icon/text color - Quasar color name (default: 'grey-7') */
  color?: string;

  /** CSS class for the icon (e.g., 'invert' for dark mode SVG icons) */
  iconClass?: string;

  /** Show a separator line before this action */
  separator?: boolean;

  /**
   * Conditional visibility function
   * Return true to show the action, false to hide
   * If not provided, action is always visible
   */
  show?: (row: any) => boolean;
}

/**
 * Configuration for a single bulk action menu item
 *
 * @example
 * // Simple action with icon
 * const deleteAction: BulkActionItem = {
 *   key: 'delete',
 *   label: 'delete',
 *   icon: 'delete',
 *   color: 'negative',
 *   minSelected: 1
 * };
 *
 * @example
 * // Action requiring multiple selections
 * const mergeAction: BulkActionItem = {
 *   key: 'merge',
 *   label: 'merge_documents',
 *   icon: 'merge_type',
 *   minSelected: 2,  // Requires at least 2 rows
 *   maxSelected: 10  // Maximum 10 rows
 * };
 *
 * @example
 * // Conditional visibility based on row status
 * const approveAction: BulkActionItem = {
 *   key: 'approve',
 *   label: 'approve',
 *   icon: 'check_circle',
 *   show: (selectedRows) => selectedRows.every(row => row.status === 'pending')
 * };
 */
export interface BulkActionItem {
  /** Unique action identifier (emitted on click) */
  key: string;

  /** Display label for the action (i18n key) */
  label: string;

  /** Material icon name (optional) */
  icon?: string;

  /** Icon/text color - Quasar color name (default: 'grey-7') */
  color?: string;

  /** CSS class for the icon (e.g., 'invert', 'white-to-red') */
  iconClass?: string;

  /** Show a separator line before this action */
  separator?: boolean;

  /**
   * Minimum number of selected rows required (action disabled if fewer)
   * @example { minSelected: 2 } // For merge action - requires 2+ rows
   */
  minSelected?: number;

  /**
   * Maximum number of selected rows allowed (action disabled if more)
   * @example { maxSelected: 1 } // For single-row export action
   */
  maxSelected?: number;

  /**
   * Conditional visibility function
   * Return true to show the action, false to hide
   * If not provided, action is always visible
   *
   * @param selectedRows - Array of currently selected row data objects
   * @param selectedCount - Number of selected rows
   * @returns true to show action, false to hide
   *
   * @example
   * // Only show for draft documents
   * show: (selectedRows) => selectedRows.every(row => row.status === 'draft')
   *
   * @example
   * // Show only when user has permission
   * show: (selectedRows, count) => userHasDeletePermission && count > 0
   */
  show?: (selectedRows: any[], selectedCount: number) => boolean;
}

/**
 * Emitted when row-level action menu item is clicked
 */
export interface RowActionPayload {
  /** The action key that was clicked */
  action: string;

  /** The row ID (stringified rowKey value) */
  rowId: string;

  /** The full row data object */
  row: any;
}

/**
 * Emitted when table row is clicked
 */
export interface RowClickPayload {
  row: any;
  rowIndex: number;
}

/**
 * Emitted when pagination changes (page or rows per page)
 */
export interface PaginationChangePayload {
  page: number;
  rowsPerPage: number;
}

/**
 * Column config for column settings
 */
export interface ColumnSettingsColumn {
  name: string;
  label?: string;
  order?: number;
  visible?: boolean;
  isCustomField?: boolean;
  [key: string]: any;
}

/**
 * Extended column config with additional properties for ColumnSettings component
 */
export interface ColumnConfig {
  /** Unique column identifier */
  name: string;
  /** Display label (or translation key) */
  label?: string;
  /** Column order/position */
  order?: number;
  /** Whether column is currently visible */
  visible?: boolean;
  /** Whether this is a custom/doc-type field (can be removed) */
  isCustomField?: boolean;
  /** Doc type key (for backwards compatibility with old component) */
  doc_type_key?: string;
  /** Internal: selected state for batch operations */
  selected?: boolean;
  /** Allow any additional properties */
  [key: string]: any;
}

/**
 * Exposed methods from ColumnSettings component for template refs
 */
export interface ColumnSettingsExposed {
  open: () => void;
  close: () => void;
  setSaving: (value: boolean) => void;
  addColumns: (columns: ColumnConfig[]) => void;
  getVisibleColumns: () => ColumnConfig[];
  getHiddenColumns: () => ColumnConfig[];
}

/**
 * Emitted when column settings are saved
 */
export interface ColumnSettingsSavePayload {
  visibleColumns: ColumnSettingsColumn[];
  hiddenColumns: ColumnSettingsColumn[];
  allColumns: ColumnSettingsColumn[];
}

// ============================================================================
// COMPONENT PROPS
// ============================================================================

/**
 * Complete props interface for UnifiedTable component
 */
export interface UnifiedTableProps {
  // =========================================================================
  // DATA
  // =========================================================================

  /** Array of row data to display */
  rows: any[];

  /** Column definitions */
  columns: UnifiedTableColumn[];

  /** Property name that uniquely identifies each row */
  rowKey?: string;

  // =========================================================================
  // STATE
  // =========================================================================

  /** Show loading indicator */
  loading?: boolean;

  /** Combined sort and pagination state (sortBy, descending, page, rowsPerPage, rowsNumber) */
  pagination?: TablePaginationState;

  /** Array of selected row IDs (controlled mode) */
  selectedRows?: string[];

  /** Initial column order (array of column names, for persistence) */
  columnOrder?: string[];

  // =========================================================================
  // FEATURES
  // =========================================================================

  /** Enable/disable table features */
  features?: Partial<TableFeatures>;

  // =========================================================================
  // STYLING & APPEARANCE
  // =========================================================================

  /** Compact mode - reduces padding and row height */
  dense?: boolean;

  /** Flat appearance - no borders or shadow */
  flatStyle?: boolean;

  /** Dark mode (auto-detected if omitted) */
  dark?: boolean;

  /** Alternate row colors */
  striped?: boolean;

  /**
   * Table height constraint (enables sticky header and scroll container)
   * CSS value like 'calc(100vh - 208px)' or '500px'
   * When set, enables overflow-y: auto and sticky thead
   */
  tableHeight?: string;

  // =========================================================================
  // BEHAVIOR
  // =========================================================================

  /** Row selection mode */
  selectableRows?: 'multiple' | 'single' | 'none';

  /** ID for column resize persistence in LocalStorage */
  tableId?: string;

  /** Whether clicking row toggles selection */
  selectOnRowClick?: boolean;

  // =========================================================================
  // ROW ACTIONS CONFIGURATION
  // =========================================================================

  /**
   * Array of row action menu items
   * Each action defines its key, label, icon, color, and optional visibility condition
   * If not provided, no actions menu will be shown (even if features.rowActions is true)
   */
  rowActions?: RowActionItem[];

  // =========================================================================
  // DISPLAY MESSAGES
  // =========================================================================

  /** Custom "no data" message */
  noDataLabel?: string;

  /** Custom loading message */
  loadingLabel?: string;

  /** CSS class for the inner q-table (controls height, scrolling, etc.) */
  tableClass?: string;

  /** Custom rows per page options for pagination dropdown (e.g., [10, 20, 25, 50]) */
  rowsPerPageOptions?: number[];

  /** Custom label for pagination size (translation key, e.g., 'supplier_per_page') */
  paginationLabel?: string;
}

// ============================================================================
// COMPONENT EMITS
// ============================================================================

/**
 * All events emitted by UnifiedTable component
 */
export interface UnifiedTableEmits {
  // Sorting
  'update:sorting': [payload: SortEventPayload];

  // Selection
  'selection-change': [payload: SelectionChangePayload];
  'toggle-all': [selectAll: boolean];

  // Actions
  'bulk-action': [payload: BulkActionPayload];
  'row-action': [payload: RowActionPayload];

  // Navigation
  'update:pagination': [payload: PaginationChangePayload];
  'row-click': [payload: RowClickPayload];

  // Column management
  'column-reorder': [columnNames: string[]];

  // Column settings
  'column-settings-open': [];
  'column-settings-save': [payload: ColumnSettingsSavePayload];
  'column-settings-cancel': [];

  // Filtering
  'update:filters': [payload: FilterChangePayload];
}

