import { onMounted, onBeforeUnmount, Ref, watch, ref } from 'vue';
import { LocalStorage } from 'quasar';
import { getUserBasedKey } from 'src/utils/cacheHelper';
import { columnResizeKey } from 'src/constants';

export interface UseTableResizableOptions {
  /** Ref to the table container element (alternative to tableId string) */
  tableRef?: Ref<HTMLElement | undefined>;
  /** Unique table ID for localStorage persistence AND DOM query fallback */
  tableId: string;
  /** Whether resizing is enabled (reactive). Defaults to true */
  enabled?: Ref<boolean>;
}

// Store event handlers for proper cleanup
interface DragHandlers {
  mousedown: (e: MouseEvent) => void;
  mouseover: (e: Event) => void;
  mouseout: (e: Event) => void;
}

/**
 * Composable for handling resizable table columns
 * Works with Composition API and template refs
 *
 * Behavior matches the original resizableGridUtil mixin:
 * - Shrink-adjacent: expanding one column shrinks the next
 * - Saves/restores widths by column name
 * - No minimum width enforcement
 *
 * @param options - Configuration options
 * @returns Object with init and cleanup methods
 */
export function useTableResizable(options: UseTableResizableOptions) {
  const { tableRef, tableId } = options;
  const enabled = options.enabled ?? ref(true);

  let dragableDivs: HTMLElement[] = [];
  const divHandlers = new WeakMap<HTMLElement, DragHandlers>();
  let isInitialized = false;
  let resizeObserver: ResizeObserver | null = null;
  let pollingTimeoutId: ReturnType<typeof setTimeout> | null = null;

  let currentResizeState: {
    curCol: HTMLElement | null;
    nxtCol: HTMLElement | null;
    pageX: number;
    curColWidth: number;
    nxtColWidth: number;
    mouseMoveHandler: ((e: MouseEvent) => void) | null;
    mouseUpHandler: ((e: MouseEvent) => void) | null;
  } = {
    curCol: null,
    nxtCol: null,
    pageX: 0,
    curColWidth: 0,
    nxtColWidth: 0,
    mouseMoveHandler: null,
    mouseUpHandler: null,
  };

  const getStyleVal = (elm: HTMLElement, css: string) => {
    return window.getComputedStyle(elm, null).getPropertyValue(css);
  };

  const paddingDiff = (col: HTMLElement) => {
    if (getStyleVal(col, 'box-sizing') === 'border-box') {
      return 0;
    }
    const padLeft = getStyleVal(col, 'padding-left');
    const padRight = getStyleVal(col, 'padding-right');
    return parseInt(padLeft) + parseInt(padRight);
  };

  const createDiv = (height: number) => {
    const div: HTMLElement = document.createElement('div');
    div.style.top = '0';
    div.style.right = '0';
    div.style.width = '9px';
    div.style.position = 'absolute';
    div.style.cursor = 'col-resize';
    div.style.userSelect = 'none';
    div.style.height = height + 'px';
    div.style.zIndex = '10';
    div.setAttribute('data-resize-handle', 'true');
    return div;
  };

  const clearResizeState = () => {
    if (currentResizeState.mouseMoveHandler) {
      document.removeEventListener('mousemove', currentResizeState.mouseMoveHandler);
    }
    if (currentResizeState.mouseUpHandler) {
      document.removeEventListener('mouseup', currentResizeState.mouseUpHandler);
    }
    currentResizeState = {
      curCol: null,
      nxtCol: null,
      pageX: 0,
      curColWidth: 0,
      nxtColWidth: 0,
      mouseMoveHandler: null,
      mouseUpHandler: null,
    };
  };

  const saveColumnWidths = (widthsByName: Record<string, number>) => {
    if (Object.keys(widthsByName).length === 0) return;

    const key = getUserBasedKey(tableId + '_' + columnResizeKey);
    try {
      LocalStorage.set(key, JSON.stringify(widthsByName));
    } catch {
      // Silently fail - localStorage may be unavailable
    }
  };

const mousedownListener = (e: MouseEvent) => {
    clearResizeState();

    e.preventDefault();
    e.stopPropagation();

    const target = e.target as HTMLElement;
    const curCol = target.parentElement as HTMLElement;
    const nxtCol = curCol?.nextElementSibling as HTMLElement;

    if (!curCol || !nxtCol) {
      return;
    }

    const padding = paddingDiff(curCol);
    currentResizeState.curCol = curCol;
    currentResizeState.nxtCol = nxtCol;
    currentResizeState.pageX = e.pageX;
    currentResizeState.curColWidth = curCol.offsetWidth - padding;
    currentResizeState.nxtColWidth = nxtCol.offsetWidth - padding;

    currentResizeState.mouseMoveHandler = (moveEvent: MouseEvent) => {
      if (!currentResizeState.curCol) return;

      const diffX = moveEvent.pageX - currentResizeState.pageX;

      if (currentResizeState.nxtCol && diffX > 0) {
        currentResizeState.nxtCol.style.width = (currentResizeState.nxtColWidth - diffX) + 'px';
        currentResizeState.nxtCol.style.minWidth = (currentResizeState.nxtColWidth - diffX) + 'px';
      }

      currentResizeState.curCol.style.width = (currentResizeState.curColWidth + diffX) + 'px';
      currentResizeState.curCol.style.minWidth = (currentResizeState.curColWidth + diffX) + 'px';
    };

    currentResizeState.mouseUpHandler = () => {
      const targetTable = tableRef?.value?.querySelector('.q-table') || tableRef?.value?.querySelector('table');
      if (targetTable) {
        const headers = targetTable.querySelectorAll('th');
        const widthsByName: Record<string, number> = {};
        headers.forEach((th: Element) => {
          const colName = th.getAttribute('data-col-name') || (th as HTMLElement).textContent?.trim();
          if (colName) {
            widthsByName[colName] = (th as HTMLElement).offsetWidth;
          }
        });
        saveColumnWidths(widthsByName);
      }

      clearResizeState();
    };

    document.addEventListener('mousemove', currentResizeState.mouseMoveHandler);
    document.addEventListener('mouseup', currentResizeState.mouseUpHandler);
  };

const setListeners = (dragableDiv: HTMLElement) => {
    const handlers: DragHandlers = {
      mousedown: mousedownListener,
      mouseover: (e: Event) => {
        const handle = e.target as HTMLElement;
        handle.classList.add('active-border-right-2px');
        const table = handle.closest('table') as HTMLElement | null;
        if (table) {
          handle.style.height = table.offsetHeight + 'px';
        }
        const th = handle.parentElement as HTMLElement | null;
        if (th && th.draggable) {
          th.dataset.resizeSuppressedDraggable = 'true';
          th.draggable = false;
        }
      },
      mouseout: (e: Event) => {
        const handle = e.target as HTMLElement;
        handle.classList.remove('active-border-right-2px');
        const table = handle.closest('table') as HTMLElement | null;
        if (table) {
          handle.style.height = getHeaderHeight(table) + 'px';
        }
        const th = handle.parentElement as HTMLElement | null;
        if (th && th.dataset.resizeSuppressedDraggable === 'true') {
          th.draggable = true;
          delete th.dataset.resizeSuppressedDraggable;
        }
      },
    };

    divHandlers.set(dragableDiv, handlers);
    dragableDiv.addEventListener('mousedown', handlers.mousedown);
    dragableDiv.addEventListener('mouseover', handlers.mouseover);
    dragableDiv.addEventListener('mouseout', handlers.mouseout);
  };

  const removeListeners = (dragableDiv: HTMLElement) => {
    const handlers = divHandlers.get(dragableDiv);
    if (handlers) {
      dragableDiv.removeEventListener('mousedown', handlers.mousedown);
      dragableDiv.removeEventListener('mouseover', handlers.mouseover);
      dragableDiv.removeEventListener('mouseout', handlers.mouseout);
      divHandlers.delete(dragableDiv);
    }
  };

const resizableGrid = (table: HTMLElement) => {
    const thead = table.querySelector('thead');
    const headerRow = thead ? thead.querySelector('tr') : table.querySelector('tr');

    if (!headerRow) {
      return;
    }

    const cols = headerRow.children;
    if (!cols || cols.length === 0) {
      return;
    }

    const headerHeight = (headerRow as HTMLElement).offsetHeight;

    for (let i = 0; i < cols.length - 1; i++) {
      const col = cols[i] as HTMLElement;

      if (col.querySelector('[data-resize-handle]')) {
        continue;
      }

      const dragableDiv = createDiv(headerHeight);
      dragableDivs.push(dragableDiv);
      col.appendChild(dragableDiv);
      col.style.position = 'relative';
      setListeners(dragableDiv);
    }
  };

  const getHeaderHeight = (table: HTMLElement): number => {
    const thead = table.querySelector('thead');
    const headerRow = thead ? thead.querySelector('tr') : table.querySelector('tr');
    return (headerRow as HTMLElement | null)?.offsetHeight ?? table.offsetHeight;
  };

  const updateResizeHandleHeights = (table: HTMLElement) => {
    const newHeight = getHeaderHeight(table);
    dragableDivs.forEach((div) => {
      div.style.height = newHeight + 'px';
    });
  };

  const setupResizeObserver = (table: HTMLElement) => {
    if (resizeObserver) {
      resizeObserver.disconnect();
    }
    resizeObserver = new ResizeObserver(() => {
      updateResizeHandleHeights(table);
    });
    resizeObserver.observe(table);
  };

  const restoreSavedColumnWidths = (table: HTMLElement) => {
    const key = getUserBasedKey(tableId + '_' + columnResizeKey);
    let savedData;

    try {
      savedData = LocalStorage.getItem(key);
    } catch {
      return;
    }

    if (!savedData) {
      return;
    }

    // Handle both string and object formats
    let columnWidths: Record<string, number> | number[];
    if (typeof savedData === 'string') {
      try {
        columnWidths = JSON.parse(savedData);
      } catch {
        return;
      }
    } else {
      columnWidths = savedData as Record<string, number> | number[];
    }

    const headers = table.querySelectorAll('th');

    if (typeof columnWidths === 'object' && !Array.isArray(columnWidths)) {
      headers.forEach((th) => {
        const colName = th.getAttribute('data-col-name') || (th as HTMLElement).textContent?.trim();
        if (colName && columnWidths[colName]) {
          const el = th as HTMLElement;
          const width = columnWidths[colName];
          el.style.width = width + 'px';
          el.style.minWidth = width + 'px';
        }
      });
    } else if (Array.isArray(columnWidths)) {
      headers.forEach((th, index) => {
        if (!columnWidths[index]) {
          return;
        }
        const el = th as HTMLElement;
        const width = columnWidths[index];
        el.style.width = width + 'px';
        el.style.minWidth = width + 'px';
      });
    }
  };

  const cancelPolling = () => {
    if (pollingTimeoutId) {
      clearTimeout(pollingTimeoutId);
      pollingTimeoutId = null;
    }
  };

  const initTableColumnResize = () => {
    if (isInitialized || !enabled.value) {
      return;
    }

    cancelPolling();

    const maxAttempts = 20; // 20 attempts * 100ms = 2 seconds max
    const pollInterval = 100; // Check every 100ms
    let attempts = 0;

    const tryInit = () => {
      attempts++;

      if (!tableRef || !tableRef.value || !enabled.value) {
        if (attempts < maxAttempts) {
          pollingTimeoutId = setTimeout(tryInit, pollInterval);
        } else {
          pollingTimeoutId = null;
        }
        return;
      }

      const tableElem: HTMLElement | null = tableRef.value.querySelector('table');
      if (!tableElem) {
        if (attempts < maxAttempts) {
          pollingTimeoutId = setTimeout(tryInit, pollInterval);
        } else {
          pollingTimeoutId = null;
        }
        return;
      }

      pollingTimeoutId = null;
      resizableGrid(tableElem);
      restoreSavedColumnWidths(tableElem);
      setupResizeObserver(tableElem);
      isInitialized = true;
    };

    tryInit();
  };

const cleanup = () => {
    cancelPolling();
    clearResizeState();

    if (resizeObserver) {
      resizeObserver.disconnect();
      resizeObserver = null;
    }

    dragableDivs.forEach((div: HTMLElement) => {
      removeListeners(div);
      if (div && div.parentElement) {
        div.parentElement.removeChild(div);
      }
    });
    dragableDivs = [];

    isInitialized = false;
  };

  watch(enabled, (newEnabled) => {
    if (newEnabled && !isInitialized) {
      initTableColumnResize();
    } else if (!newEnabled && isInitialized) {
      cleanup();
    }
  });

  onMounted(() => {
    if (enabled.value) {
      initTableColumnResize();
    }
  });

  onBeforeUnmount(() => {
    cleanup();
  });

  return {
    initTableColumnResize,
    cleanup,
  };
}
