<template>
  <q-icon
    class="column-header-filter"
    :class="{ 'filter-active': hasValue }"
    name="menu"
    size="18px"
    :data-test="'column-filter-trigger-' + column"
    @click.stop.prevent
  >
    <q-menu
      v-model="menuOpen"
      transition-show="jump-down"
      transition-hide="jump-up"
      anchor="bottom middle"
      self="top middle"
      @before-hide="onMenuHide"
    >
      <div class="column-header-filter-menu" :data-test="'column-filter-menu-' + column">
        <!-- Operator Selector -->
        <q-select
          v-model="selectedOperator"
          :options="operatorOptions"
          :label="$t('search_operator')"
          outlined
          dense
          emit-value
          map-options
          class="filter-operator-select"
        >
          <template v-slot:selected-item="scope">
            <div class="ellipsis">{{ $t(scope.opt.label) }}</div>
          </template>
          <template v-slot:option="scope">
            <q-item v-bind="scope.itemProps">
              <q-item-section>{{ $t(scope.opt.label) }}</q-item-section>
            </q-item>
          </template>
        </q-select>

        <!-- Text Input (for text/number types) -->
        <q-input
          v-if="type !== 'date' && type !== 'select'"
          v-model="inputValue"
          :label="$t('filter')"
          outlined
          dense
          debounce="300"
          color="primary"
          class="filter-value-input"
          data-test="column-filter-input"
          @keyup.enter="applyFilter"
        >
          <template v-slot:append>
            <q-icon
              name="close"
              class="cursor-pointer clear-icon"
              :class="{ 'clear-icon-hidden': !inputValue }"
              size="xs"
              @click="inputValue = ''"
            />
          </template>
        </q-input>

        <!-- Date Picker (for date type) -->
        <q-input
          v-if="type === 'date'"
          v-model="inputValue"
          :label="$t('filter')"
          outlined
          dense
          clearable
          class="filter-value-input"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy cover transition-show="scale" transition-hide="scale">
                <q-date
                  v-model="inputValue"
                  mask="YYYY-MM-DD"
                  @update:model-value="applyFilter"
                >
                  <div class="row items-center justify-end">
                    <q-btn v-close-popup :label="$t('close')" color="primary" flat />
                  </div>
                </q-date>
              </q-popup-proxy>
            </q-icon>
          </template>
        </q-input>

        <!-- Select Dropdown (for select type) -->
        <q-select
          v-if="type === 'select' && selectOptions.length > 0"
          v-model="inputValue"
          :options="selectOptions"
          :label="$t('filter')"
          outlined
          dense
          emit-value
          map-options
          clearable
          class="filter-value-input"
          @update:model-value="applyFilter"
        />

        <!-- Action Buttons -->
        <div class="filter-actions">
          <q-btn
            flat
            dense
            color="grey-7"
            :label="$t('clear')"
            data-test="column-filter-clear"
            @click="clearFilter"
            :disable="!hasValue && !inputValue"
          />
          <q-btn
            flat
            dense
            color="primary"
            :label="$t('apply')"
            data-test="column-filter-apply"
            @click="applyFilter"
            :disable="!inputValue"
          />
        </div>
      </div>
    </q-menu>
  </q-icon>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import type { FilterOperator, ColumnFilterType } from './types/table/unified-table';

export default defineComponent({
  name: 'ColumnHeaderFilter',
  props: {
    /** Column name */
    column: {
      type: String,
      required: true,
    },
    /** Filter type (text, date, number, select) */
    type: {
      type: String as PropType<ColumnFilterType>,
      default: 'text',
    },
    /** Current filter value */
    value: {
      type: [String, Number] as PropType<string | number>,
      default: '',
    },
    /** Current filter operator */
    operator: {
      type: String as PropType<FilterOperator>,
      default: 'contains',
    },
    /** Available operators */
    operators: {
      type: Array as PropType<Array<{ label: string; value: FilterOperator }>>,
      default: () => [],
    },
    /** Options for select type */
    options: {
      type: Array as PropType<Array<{ label: string; value: string | number }>>,
      default: () => [],
    },
  },
  emits: ['update:filter', 'clear'],
  data() {
    // Determine the appropriate default operator based on filter type
    // If type is 'date' and operator is 'contains' (text default), use 'equal' instead
    const defaultOperator = this.type === 'date' && this.operator === 'contains'
      ? 'equal' as FilterOperator
      : this.operator as FilterOperator;

    return {
      menuOpen: false,
      inputValue: (this.value || '') as string | number,
      selectedOperator: defaultOperator,
    };
  },
  computed: {
    hasValue(): boolean {
      return this.value !== '' && this.value !== null && this.value !== undefined;
    },
    operatorOptions(): Array<{ label: string; value: string }> {
      if (this.operators.length > 0) {
        return this.operators;
      }
      // Defaults based on type
      if (this.type === 'date') {
        return [
          { label: 'equal', value: 'equal' },
          { label: 'before', value: 'before' },
          { label: 'after', value: 'after' },
        ];
      }
      return [
        { label: 'contains', value: 'contains' },
        { label: 'exact', value: 'exact' },
        { label: 'starts_with', value: 'starts_with' },
        { label: 'ends_with', value: 'ends_with' },
        { label: 'smart', value: 'smart' },
      ];
    },
    selectOptions(): Array<{ label: string; value: string | number }> {
      return this.options || [];
    },
  },
  watch: {
    value(newVal: string | number): void {
      this.inputValue = newVal || '';
    },
    operator(newVal: FilterOperator): void {
      this.selectedOperator = newVal;
    },
  },
  methods: {
    applyFilter(): void {
      if (this.inputValue !== '' && this.inputValue !== null && this.inputValue !== undefined) {
        this.$emit('update:filter', {
          column: this.column,
          value: this.inputValue,
          operator: this.selectedOperator,
        });
      }
      this.menuOpen = false;
    },
    clearFilter(): void {
      this.inputValue = '';
      this.$emit('clear', this.column);
      this.menuOpen = false;
    },
    onMenuHide(): void {
      // Reset input to current filter value
      this.inputValue = this.value || '';
      // Reset operator, but ensure it's valid for the filter type
      this.selectedOperator = this.type === 'date' && this.operator === 'contains'
        ? 'equal'
        : this.operator;
    },
  },
});
</script>

