<template>
  <span
    class="sort-indicator"
    @click="cycleSort"
  >
    <!-- Default: both arrows (unsorted) -->
    <template v-if="!isActive">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="m7 15 5 5 5-5"/>
        <path d="m7 9 5-5 5 5"/>
      </svg>
    </template>

    <!-- Ascending: single up arrow in primary -->
    <template v-else-if="currentDirection === 'asc'">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="sort-active">
        <path d="m18 15-6-6-6 6"/>
      </svg>
    </template>

    <!-- Descending: single down arrow in primary -->
    <template v-else>
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="sort-active">
        <path d="m6 9 6 6 6-6"/>
      </svg>
    </template>
  </span>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';

export default defineComponent({
  name: 'ColumnOrderBy',
  props: {
    column: {
      type: String,
      required: true,
    },
    currentSort: {
      type: String as PropType<string | null>,
      default: null,
    },
    currentDirection: {
      type: String as PropType<'asc' | 'desc' | null>,
      default: null,
    },
    mode: {
      type: String as PropType<'client' | 'server'>,
      default: 'client',
    },
  },
  emits: ['sort'],
  computed: {
    isActive(): boolean {
      return this.currentSort === this.column;
    },
  },
  methods: {
    cycleSort(): void {
      if (!this.isActive) {
        // Not sorted → sort descending
        this.$emit('sort', { column: this.column, direction: 'desc' });
      } else if (this.currentDirection === 'desc') {
        // Descending → sort ascending
        this.$emit('sort', { column: this.column, direction: 'asc' });
      } else {
        // Ascending → clear sort (back to default)
        this.$emit('sort', { column: this.column, direction: null });
      }
    },
  },
});
</script>

<style scoped lang="scss">
.sort-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  vertical-align: middle;
  margin-left: 4px;
  color: var(--muted-foreground);
  opacity: 0.7;
  transition: opacity 150ms ease;

  &:hover {
    opacity: 1;
  }
}

// Show sort icons only on hover unless actively sorted
th:hover .sort-indicator {
  opacity: 0.7;

  &:hover {
    opacity: 1;
  }
}

.sort-active {
  color: var(--primary);
  opacity: 1;
}

// When column is actively sorted, always show
.sort-indicator:has(.sort-active) {
  opacity: 1;
}
</style>
