<template>
  <q-checkbox
    :model-value="isSelected"
    :indeterminate="isIndeterminate"
    @update:model-value="handleToggle"
    :disable="disabled"
    :aria-label="ariaLabel"
    dense
  />
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  name: 'RowSelectionCheckbox',
  props: {
    /** Unique identifier for the row */
    rowId: {
      type: String,
      required: true,
    },
    /** Whether this specific row is selected */
    isSelected: {
      type: Boolean,
      required: true,
    },
    /** Whether this is a master checkbox (select all) */
    isMaster: {
      type: Boolean,
      default: false,
    },
    /** For master checkbox: total number of rows */
    totalRows: {
      type: Number,
      default: 0,
    },
    /** For master checkbox: number of selected rows */
    selectedCount: {
      type: Number,
      default: 0,
    },
    /** Whether the checkbox should be disabled */
    disabled: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['toggle', 'toggle-all'],
  computed: {
    /**
     * Computed property for indeterminate state (master checkbox with partial selection)
     */
    isIndeterminate(): boolean {
      if (!this.isMaster) {
        return false;
      }
      // Indeterminate when some (but not all) rows are selected
      return this.selectedCount > 0 && this.selectedCount < this.totalRows;
    },
    /**
     * Computed property for aria-label
     */
    ariaLabel(): string {
      if (this.isMaster) {
        return 'Select all rows';
      }
      return `Select row ${this.rowId}`;
    },
  },
  methods: {
    /**
     * Handle checkbox toggle
     */
    handleToggle(value: boolean): void {
      if (this.isMaster) {
        this.$emit('toggle-all', value);
      } else {
        this.$emit('toggle', this.rowId, value);
      }
    },
  },
});
</script>

<style scoped lang="scss">
:deep(.q-checkbox__inner) {
  padding: 2px;
}
</style>
