import { ref, computed, Ref, ComputedRef, watch } from 'vue';
import { LocalStorage } from 'quasar';
import { notify } from 'src/components/notifications/notify';
import type {
  FilterOperator,
  ColumnFilterValue,
  ColumnFilterConfig,
  ColumnFilterType,
  FilterChangePayload,
  UnifiedTableColumn,
  TextFilterOperator,
  DateFilterOperator,
} from 'src/components/Table/types/table/unified-table';
import {
  TEXT_FILTER_OPERATORS,
  DATE_FILTER_OPERATORS,
} from 'src/components/Table/types/table/unified-table';
import { tableFilterStorageKey } from 'src/constants';

export interface ColumnFilterState {
  value: string | number;
  operator: FilterOperator;
}

export interface UseColumnFilterOptions {
  /** Column definitions to determine filter types */
  columns: Ref<UnifiedTableColumn[]> | ComputedRef<UnifiedTableColumn[]>;
  /** Callback when filters change */
  onFilterChange?: (payload: FilterChangePayload) => void;
  /** Initial filter values */
  initialFilters?: ColumnFilterValue[];
  /** Whether to use AND (true) or OR (false) for matching - default false */
  matchAll?: boolean;
  /** Storage key for persisting filters to localStorage (e.g., tableId) */
  storageKey?: string;
}

export interface UseColumnFilterReturn {
  /** Current filter values per column */
  filterValues: Ref<Record<string, ColumnFilterState>>;
  /** Array of active filters */
  activeFilters: ComputedRef<ColumnFilterValue[]>;
  /** Whether any filters are active */
  hasActiveFilters: ComputedRef<boolean>;
  /** Number of active filters */
  activeFilterCount: ComputedRef<number>;
  /** Set filter for a specific column */
  setFilter: (column: string, value: string | number, operator: FilterOperator) => void;
  /** Clear filter for a specific column */
  clearFilter: (column: string) => void;
  /** Clear all filters */
  clearAllFilters: () => void;
  /** Apply client-side filtering to rows */
  filterRows: (rows: any[]) => any[];
  /** Generate JSON string for server-side filtering */
  toFilterJson: () => string;
  /** Get filter config for a column */
  getColumnFilterConfig: (column: UnifiedTableColumn) => ColumnFilterConfig | null;
  /** Get filter type for a column */
  getColumnFilterType: (column: UnifiedTableColumn) => ColumnFilterType;
  /** Get available operators for a column */
  getColumnOperators: (column: UnifiedTableColumn) => Array<{ label: string; value: FilterOperator }>;
  /** Check if column is filterable */
  isFilterable: (column: UnifiedTableColumn) => boolean;
}

/** For a caller that owns its filter lifetime instead of letting it outlive the view. */
export function clearPersistedColumnFilters(storageKey: string): void {
  LocalStorage.remove(`${tableFilterStorageKey}${storageKey}`);
}

/**
 * Get the value a filter compares against for one row and column.
 *
 * When the column defines filterValue, the formatted display string is returned
 * so text filters match what the user sees (e.g. localized dates).
 */
export function getColumnFilterRowValue(
  row: any,
  column: string,
  columns: UnifiedTableColumn[],
): any {
  // Look up column definition to get field accessor
  const colDef = columns.find((c) => c.name === column);

  // Resolve the raw value
  let rawValue: any;
  if (column.includes('.')) {
    rawValue = column.split('.').reduce((obj, key) => obj?.[key], row);
  } else if (colDef) {
    rawValue =
      typeof colDef.field === 'function'
        ? colDef.field(row)
        : row[colDef.field as string];
  } else {
    rawValue = row[column];
  }

  // Apply filterValue transform when provided
  if (colDef?.filterValue) {
    return colDef.filterValue(rawValue, row);
  }

  return rawValue;
}

/**
 * Match a single value against a single filter.
 */
export function matchColumnFilter(
  rowValue: any,
  filterValue: string | number,
  operator: FilterOperator,
): boolean {
  if (rowValue === null || rowValue === undefined) return false;

  const strRowValue = String(rowValue).toLowerCase();
  const strFilterValue = String(filterValue).toLowerCase();

  switch (operator) {
    case 'contains':
      return strRowValue.includes(strFilterValue);

    case 'exact':
      return strRowValue === strFilterValue;

    case 'starts_with':
      return strRowValue.startsWith(strFilterValue);

    case 'ends_with':
      return strRowValue.endsWith(strFilterValue);

    case 'smart': {
      // Smart search: split by spaces and check if all words are present
      const words = strFilterValue.split(/\s+/).filter(Boolean);
      return words.every((word) => strRowValue.includes(word));
    }

    case 'equal': {
      // For dates: compare just the date part (ignore time)
      const rowDate = new Date(rowValue);
      const filterDate = new Date(filterValue as string);
      if (isNaN(rowDate.getTime()) || isNaN(filterDate.getTime())) return false;
      // Compare year, month, day only
      return rowDate.getFullYear() === filterDate.getFullYear() &&
             rowDate.getMonth() === filterDate.getMonth() &&
             rowDate.getDate() === filterDate.getDate();
    }

    case 'before': {
      // For dates: row date is before filter date
      const rowDate = new Date(rowValue);
      const filterDate = new Date(filterValue as string);
      // Validate both dates are valid before comparing
      if (isNaN(rowDate.getTime()) || isNaN(filterDate.getTime())) return false;
      return rowDate < filterDate;
    }

    case 'after': {
      // For dates: row date is after filter date
      const rowDate = new Date(rowValue);
      const filterDate = new Date(filterValue as string);
      // Validate both dates are valid before comparing
      if (isNaN(rowDate.getTime()) || isNaN(filterDate.getTime())) return false;
      return rowDate > filterDate;
    }

    default:
      return strRowValue.includes(strFilterValue);
  }
}

/**
 * Apply column filters to a set of rows.
 *
 * Exported as a pure function because column filters are client-side: a host
 * that lets the server page its rows must run this over the WHOLE result set
 * before it cuts a page out of it. Filtering a page the server already cut
 * leaves the matches scattered over the pages they happened to land on, and the
 * pager keeps counting the rows the filter hides (BOL-498).
 *
 * matchAll = true: every filter must match (AND); false: any filter may (OR).
 */
export function applyColumnFilters(
  rows: any[],
  filters: ColumnFilterValue[],
  columns: UnifiedTableColumn[],
  matchAll = false,
): any[] {
  if (!Array.isArray(rows) || filters.length === 0) return rows;

  return rows.filter((row) => {
    const results = filters.map((filter) =>
      matchColumnFilter(
        getColumnFilterRowValue(row, filter.column, columns),
        filter.value,
        filter.operator,
      ),
    );

    return matchAll ? results.every(Boolean) : results.some(Boolean);
  });
}

/**
 * Composable for managing column filters in DocBitsTable
 */
export function useColumnFilter(options: UseColumnFilterOptions): UseColumnFilterReturn {
  const { columns, onFilterChange, initialFilters = [], matchAll = false, storageKey } = options;

  // Build the full storage key
  const fullStorageKey = storageKey ? `${tableFilterStorageKey}${storageKey}` : null;

  // Track if we've already shown a storage error notification
  let hasShownStorageError = false;

  // Load saved filters from localStorage
  function loadFiltersFromStorage(): Record<string, ColumnFilterState> {
    if (!fullStorageKey) return {};
    try {
      const saved = LocalStorage.getItem<Record<string, ColumnFilterState>>(fullStorageKey);
      return saved || {};
    } catch {
      if (!hasShownStorageError) {
        hasShownStorageError = true;
        notify.warning('Could not restore saved filters');
      }
      return {};
    }
  }

  // Save filters to localStorage
  function saveFiltersToStorage(filters: Record<string, ColumnFilterState>): void {
    if (!fullStorageKey) return;
    try {
      if (Object.keys(filters).length === 0) {
        LocalStorage.remove(fullStorageKey);
      } else {
        LocalStorage.set(fullStorageKey, filters);
      }
    } catch {
      if (!hasShownStorageError) {
        hasShownStorageError = true;
        notify.warning('Could not save filters');
      }
    }
  }

  // Filter values state: { columnName: { value, operator } }
  // Initialize from localStorage first, then override with initial filters if provided
  // Use spread operator to create a new object reference for proper reactivity
  const savedFilters = loadFiltersFromStorage();
  const filterValues = ref<Record<string, ColumnFilterState>>({ ...savedFilters });

  // Initialize from initial filters (overrides saved filters)
  if (initialFilters.length > 0) {
    initialFilters.forEach((filter) => {
      filterValues.value[filter.column] = {
        value: filter.value,
        operator: filter.operator,
      };
    });
  }

  // Watch for filter changes and persist to localStorage
  watch(
    filterValues,
    (newFilters) => {
      saveFiltersToStorage(newFilters);
    },
    { deep: true }
  );

  /**
   * Get filter configuration for a column
   */
  function getColumnFilterConfig(column: UnifiedTableColumn): ColumnFilterConfig | null {
    if (column.filter === false) return null;
    if (column.filter === true || column.filter === undefined) {
      return { type: 'text', filterable: true };
    }
    return column.filter;
  }

  /**
   * Check if column is filterable
   */
  function isFilterable(column: UnifiedTableColumn): boolean {
    // Action column is never filterable
    if (column.name === '__actions__') return false;

    const config = getColumnFilterConfig(column);
    if (!config) return false;
    return config.filterable !== false;
  }

  /**
   * Get filter type for a column
   * Auto-detects date type from column name
   */
  function getColumnFilterType(column: UnifiedTableColumn): ColumnFilterType {
    const config = getColumnFilterConfig(column);
    if (config?.type) return config.type;

    // Auto-detect date columns from name
    const name = column.name.toLowerCase();
    if (name.includes('date') || name.includes('_at') || name.includes('time')) {
      return 'date';
    }

    return 'text';
  }

  /**
   * Get available operators for a column
   */
  function getColumnOperators(column: UnifiedTableColumn): Array<{ label: string; value: FilterOperator }> {
    const config = getColumnFilterConfig(column);
    const type = getColumnFilterType(column);

    // Custom operators if specified
    if (config?.operators) {
      return config.operators.map((op) => ({ label: op, value: op }));
    }

    // Default operators based on type
    if (type === 'date') {
      return DATE_FILTER_OPERATORS;
    }

    return TEXT_FILTER_OPERATORS;
  }

  /**
   * Computed: array of active filters
   */
  const activeFilters = computed<ColumnFilterValue[]>(() => {
    const filters: ColumnFilterValue[] = [];

    for (const [column, state] of Object.entries(filterValues.value)) {
      if (state.value !== '' && state.value !== null && state.value !== undefined) {
        filters.push({
          column,
          operator: state.operator,
          value: state.value,
        });
      }
    }

    return filters;
  });

  /**
   * Computed: whether any filters are active
   */
  const hasActiveFilters = computed(() => activeFilters.value.length > 0);

  /**
   * Computed: number of active filters
   */
  const activeFilterCount = computed(() => activeFilters.value.length);

  /**
   * Set filter for a specific column
   */
  function setFilter(column: string, value: string | number, operator: FilterOperator): void {
    filterValues.value[column] = { value, operator };
    emitFilterChange();
  }

  /**
   * Clear filter for a specific column
   */
  function clearFilter(column: string): void {
    delete filterValues.value[column];
    emitFilterChange();
  }

  /**
   * Clear all filters
   */
  function clearAllFilters(): void {
    filterValues.value = {};
    emitFilterChange();
  }

  /**
   * Emit filter change event
   */
  function emitFilterChange(): void {
    if (onFilterChange) {
      onFilterChange({
        filters: activeFilters.value,
        filterJson: toFilterJson(),
        matchAll,
      });
    }
  }

  /**
   * Generate JSON string for server-side filtering
   * Format: { filters: [{ field, operator, value }], match_all: false }
   */
  function toFilterJson(): string {
    const filters = activeFilters.value.map((f) => ({
      field: f.column,
      operator: f.operator,
      value: f.value,
    }));

    return JSON.stringify({
      filters,
      match_all: matchAll,
    });
  }

  /**
   * Apply client-side filtering to rows.
   *
   * Shares its predicate with applyColumnFilters, so a host that pre-filters the
   * full server result set (see BOL-498) hands over rows this call leaves as-is.
   */
  function filterRows(rows: any[]): any[] {
    if (!hasActiveFilters.value) return rows;

    return applyColumnFilters(rows, activeFilters.value, columns.value, matchAll);
  }

  return {
    filterValues,
    activeFilters,
    hasActiveFilters,
    activeFilterCount,
    setFilter,
    clearFilter,
    clearAllFilters,
    filterRows,
    toFilterJson,
    getColumnFilterConfig,
    getColumnFilterType,
    getColumnOperators,
    isFilterable,
  };
}
