<template>
  <div ref="tableWrapperRef" class="docbits-table-wrapper" :class="tableClasses">
    <!-- Main Table Container -->
    <div
      class="docbits-table-container"
      :class="[containerClasses, { 'has-height': !!tableHeight }]"
      :style="containerStyle"
    >
      <!-- Table -->
      <q-table
        ref="tableRef"
        :id="tableId || 'docbits-table'"
        :rows="paginatedRows"
        :columns="displayColumns"
        :row-key="rowKey"
        :loading="loading"
        v-model:pagination="paginationSync"
        :rows-per-page-options="rowsPerPageOptions"
        :visible-columns="visibleColumns"
        hide-pagination
        hide-bottom
        flat
        class="docbits-table dashboard-table-style"
        :class="[tableClass, { 'resizable': featuresComputed.resizable }]"
        :style="tableHeight ? { height: 'auto', flex: '1 1 auto', minHeight: 0, overflowY: 'auto' } : {}"
        @request="onTableRequest"
      >
        <!-- Header with Sort Arrows -->
        <template v-slot:header="props">
          <q-tr :props="props">
            <!-- Master Checkbox (if selection enabled) -->
            <q-th
              v-if="featuresComputed.selection"
              auto-width
              class="selection-column"
              data-col-name="__selection__"
              :style="featuresComputed.resizable ? 'width: 50px; min-width: 50px;' : ''"
            >
              <div class="selection-header-content">
                <RowSelectionCheckbox
                  row-id="__master__"
                  :is-selected="allRowsSelected"
                  is-master
                  :total-rows="rows.length"
                  :selected-count="selectedCount"
                  @toggle-all="handleMasterToggle"
                />
                <!-- Header Actions Slot (for bulk actions menu, etc.) -->
                <slot name="header-actions" :selected-count="selectedCount" :selected-rows="selectedRowsSet" />
              </div>
            </q-th>

            <!-- Data Columns with Sort Arrows and Drag-Drop -->
            <q-th
              v-for="(col, colIndex) in props.cols"
              :key="col.name"
              :props="props"
              :data-col-name="col.name"
              :data-test="'table-column-' + col.name"
              :style="col.headerStyle"
              :class="[
                col.headerClasses,
                { 'action-column-header': isNonDraggableColumn(col.name) },
                { 'draggable-column': featuresComputed.columnReorder && !isNonDraggableColumn(col.name) }
              ]"
              :auto-width="isNonDraggableColumn(col.name)"
              class="column-header"
              :draggable="featuresComputed.columnReorder && !isNonDraggableColumn(col.name)"
              @dragstart="featuresComputed.columnReorder && dragDrop.onDragStart($event, displayColumns, Number(colIndex))"
              @dragover="featuresComputed.columnReorder && dragDrop.onDragOver($event, Number(colIndex))"
              @drop="featuresComputed.columnReorder && dragDrop.onDrop($event, Number(colIndex))"
            >
              <div class="column-header-wrapper" :class="{ 'action-header': col.name === '__actions__' }">
                <span>{{ col.label }}</span>

                <!-- Icons container - pushed to right -->
                <div class="column-header-icons">
                  <!-- Sort Arrow Component -->
                  <!-- Only render for columns where canSort is true (respects column.sortable setting) -->
                  <ColumnOrderBy
                    v-if="featuresComputed.sorting && col.canSort"
                    :column="col.name"
                    :current-sort="effectiveSortBy"
                    :current-direction="effectiveSortBy === col.name ? (effectiveSortDescending ? 'desc' : 'asc') : null"
                    mode="client"
                    @sort="handleColumnSort"
                  />

                  <!-- Column Filter Component -->
                  <ColumnHeaderFilter
                    v-if="featuresComputed.filtering && isColumnFilterable(col)"
                    :column="col.name"
                    :type="getColumnFilterType(col)"
                    :value="columnFilter.filterValues.value[col.name]?.value || ''"
                    :operator="columnFilter.filterValues.value[col.name]?.operator || 'contains'"
                    :operators="getColumnFilterOperators(col)"
                    :options="getColumnFilterOptions(col)"
                    @update:filter="handleFilterUpdate"
                    @clear="handleFilterClear"
                  />
                </div>
              </div>
            </q-th>
          </q-tr>
        </template>

        <!-- Body -->
        <template v-slot:body="props">
          <q-tr
            :props="props"
            :id="'row_' + props.row[rowKey]"
            class="data-row"
            :class="[
              {
                'row-selected': selectedRowsSet.has(String(props.row[rowKey])),
                'group-row': isGroupRow(props.row),
                'group-child-row': props.row?._group_child === true,
                'group-summary-row': isGroupSummaryRow(props.row),
              },
              rowClass ? rowClass(props.row) : '',
            ]"
            data-test="table-row"
            :data-row-id="String(props.row[rowKey])"
            @click="handleRowClick($event, props.row, props.rowIndex)"
          >
            <!-- Row Checkbox (if selection enabled) -->
            <q-td
              v-if="featuresComputed.selection"
              auto-width
              class="selection-column"
              :style="featuresComputed.resizable ? 'width: 50px; min-width: 50px;' : ''"
              @click.stop
            >
              <RowSelectionCheckbox
                v-if="!isGroupSummaryRow(props.row)"
                :row-id="String(props.row[rowKey])"
                :is-selected="selectedRowsSet.has(String(props.row[rowKey]))"
                :disabled="isGroupRow(props.row)"
                @toggle="handleRowToggle"
              />
            </q-td>


            <!-- Data Cells (excluding action column which is rendered separately) -->
            <q-td
              v-for="col in props.cols.filter(c => c.name !== '__actions__')"
              :key="col.name"
              :props="props"
              :style="col.style"
              :class="[col.classes, 'max-width-160', 'ellipsify']"
              class="data-cell"
              :data-test="'table-cell-' + col.name"
            >
              <template v-if="isGroupSummaryRow(props.row)">
                <span
                  v-if="isGroupSummaryLabelCell(col)"
                  class="docbits-group-summary__label"
                >
                  Aggregates
                </span>
                <span
                  v-else-if="hasGroupAggregateValue(props.row, col)"
                  class="docbits-group-summary__aggregate"
                >
                  <span class="docbits-group-summary__operation">
                    {{ groupAggregateOperationLabel(props.row, col) }}
                  </span>
                  <strong>{{ formatGroupAggregateValue(groupAggregateValue(props.row, col), col) }}</strong>
                  <q-tooltip>
                    {{ groupAggregateOperationLabel(props.row, col) }}
                    {{ formatGroupAggregateValue(groupAggregateValue(props.row, col), col) }}
                  </q-tooltip>
                </span>
              </template>

              <template v-else-if="isGroupRow(props.row)">
                <div
                  v-if="isGroupValueCell(props.row, col)"
                  class="docbits-group-expander"
                  @click.stop="handleGroupRowToggle($event, props.row, props.rowIndex)"
                  @mouseenter="handleGroupPrefetch(props.row, props.rowIndex)"
                  @mouseleave="handleGroupPrefetchCancel(props.row, props.rowIndex)"
                  @focusin="handleGroupPrefetch(props.row, props.rowIndex)"
                  @focusout="handleGroupPrefetchCancel(props.row, props.rowIndex)"
                >
                  <q-btn
                    flat
                    dense
                    :icon="
                      props.row._group_loading
                        ? 'hourglass_empty'
                        : props.row._group_expanded
                        ? 'keyboard_arrow_down'
                        : 'keyboard_arrow_right'
                    "
                    class="docbits-group-expander__button"
                  />
                  <span class="docbits-group-expander__label">
                    {{ groupRowLabel(props.row) }}
                  </span>
                </div>
              </template>

              <!-- Slot for custom cell rendering -->
              <slot
                v-else
                :name="`body-cell-${col.name}`"
                :row="props.row"
                :rowIndex="props.rowIndex"
                :col="col"
                :expanded="featuresComputed.expandable && expandedRowsSet.has(String(props.row[rowKey]))"
              >
                {{ col.value || '-' }}
                <q-tooltip v-if="col.value">{{ col.value }}</q-tooltip>
              </slot>
            </q-td>

            <!-- Row Actions Menu (if enabled and actions defined) -->
            <q-td
              v-if="featuresComputed.rowActions && rowActions.length > 0"
              auto-width
              class="action-column"
            >
              <RowActionsMenu
                v-if="!isGroupSummaryRow(props.row)"
                :actions="rowActions"
                :row="props.row"
                @action="(key) => handleRowAction(key, props.row)"
              />
            </q-td>
          </q-tr>

          <!-- Expandable full-width detail row (features.expandable) -->
          <q-tr
            v-if="featuresComputed.expandable && expandedRowsSet.has(String(props.row[rowKey]))"
            :props="props"
            class="row-detail"
            :data-row-id="String(props.row[rowKey])"
          >
            <q-td
              :colspan="
                props.cols.filter((c) => c.name !== '__actions__').length +
                (featuresComputed.selection ? 1 : 0) +
                (featuresComputed.rowActions && rowActions.length > 0 ? 1 : 0)
              "
            >
              <slot name="row-detail" :row="props.row" :rowIndex="props.rowIndex" />
            </q-td>
          </q-tr>
        </template>

        <!-- No Data State (only shown after initial load completes) -->
        <template v-slot:bottom-row>
          <q-tr
            v-if="rows.length === 0 && !loading && hasLoadedOnce"
            data-test="table-empty-state"
          >
            <q-td class="text-center" :colspan="displayColumns.length + (featuresComputed.selection ? 1 : 0)">
              {{ $t(noDataLabel) }}
            </q-td>
          </q-tr>
        </template>
      </q-table>

      <!-- Skeleton Loading Overlay -->
      <div
        v-if="loading && rows.length === 0"
        class="skeleton-loading-container"
        :class="{ 'has-pagination': featuresComputed.pagination }"
        data-test="table-loading"
      >
        <table class="skeleton-table">
          <tbody>
            <tr v-for="n in skeletonRowCount" :key="'skeleton-' + n" class="skeleton-row">
              <!-- Selection column skeleton -->
              <td v-if="featuresComputed.selection" class="skeleton-selection-cell">
                <div class="skeleton-cell skeleton-checkbox"></div>
              </td>
              <!-- Data columns skeleton -->
              <td v-for="col in displayColumns" :key="col.name" class="skeleton-data-cell">
                <div class="skeleton-cell" :class="{ 'skeleton-small': col.name === '__actions__' }"></div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Custom Pagination (matching main dashboard style) -->
      <div
        v-if="featuresComputed.pagination"
        class="pagination-container flex justify-end"
        :class="{ 'skeleton-active': loading && rows.length === 0 }"
      >
        <div class="row items-center" style="margin-right: 0;">
          <!-- Total Records Indicator -->
          <div
            v-if="totalRowsCount > 0"
            class="docbits-pagination-total q-mr-md"
            data-testid="docbits-table-total-count"
            data-test="table-total-count"
          >
            {{ totalRowsCount }} {{ $t('total') }}
          </div>
          <!-- Page Size Selector -->
          <PaginationSettings
            :label="paginationLabel"
            :settings-key="paginationSettingsKey"
            :options="pageSizeOptionsStrings"
            :model-value="currentPageSize"
            @update:model-value="handlePageSizeChange"
          />
          <q-separator vertical class="q-mx-md" />
          <!-- Page Navigation -->
          <q-pagination
            :model-value="currentPage"
            color="primary"
            :max="totalPages"
            class="q-py-xs docbits-pagination"
            :max-pages="6"
            input
            boundary-links
            gutter="none"
            @update:model-value="handlePageChange"
          />
        </div>
      </div>
    </div>

    <!-- Bulk Actions: Use #header-actions slot with BulkActionsMenu component -->
  </div>
</template>

<script lang="ts">
import { QTable } from 'quasar';
import { useTranslate } from '@tolgee/vue';
import ColumnOrderBy from './ColumnOrderBy.vue';
import RowActionsMenu from './RowActionsMenu.vue';
import ColumnHeaderFilter from './ColumnHeaderFilter.vue';
import PaginationSettings from './PaginationSettings.vue';
import RowSelectionCheckbox from './RowSelectionCheckbox.vue';
import { ref, computed, defineComponent, PropType } from 'vue';
import { useDragDropColumn } from './composables/useDragDropColumn';
import { useTableResizable } from './composables/useTableResizable';
import { useColumnFilter } from './composables/useColumnFilter';
import { useDashboardStore } from 'src/store/main';
import { toPositiveInt } from 'src/utils/general';
import type {
  TableFeatures,
  UnifiedTableColumn,
  SortEventPayload,
  RowActionItem,
  TablePaginationState,
  ColumnFilterValue,
  FilterOperator,
  FilterChangePayload,
} from './types/table/unified-table';

export default defineComponent({
  name: 'DocBitsTable',
  components: {
    ColumnOrderBy,
    RowSelectionCheckbox,
    RowActionsMenu,
    ColumnHeaderFilter,
    PaginationSettings,
  },
  props: {
    /** Array of row data to display */
    rows: {
      type: Array as PropType<any[]>,
      required: true,
    },
    /** Column definitions */
    columns: {
      type: Array as PropType<UnifiedTableColumn[]>,
      required: true,
    },
    /** Property name that uniquely identifies each row */
    rowKey: {
      type: String,
      default: 'id',
    },
    /** Show loading indicator */
    loading: {
      type: Boolean,
      default: false,
    },
    /** Compact mode - reduces padding and row height */
    dense: {
      type: Boolean,
      default: false,
    },
    /** Flat appearance - no borders or shadow */
    flatStyle: {
      type: Boolean,
      default: false,
    },
    /** Alternate row colors */
    striped: {
      type: Boolean,
      default: false,
    },
    /** Dark mode (auto-detected if omitted) */
    dark: {
      type: Boolean,
      default: false,
    },
    /** Row selection mode */
    selectableRows: {
      type: String as PropType<'multiple' | 'single' | 'none'>,
      default: 'multiple',
    },
    /** Whether clicking row toggles selection */
    selectOnRowClick: {
      type: Boolean,
      default: false,
    },
    /** Array of row action menu items */
    rowActions: {
      type: Array as PropType<RowActionItem[]>,
      default: () => [],
    },
    /** Optional class(es) applied to each row, resolved per-row */
    rowClass: {
      type: Function as PropType<(row: any) => string | Record<string, boolean> | undefined>,
      default: undefined,
    },
    /** Custom "no data" message */
    noDataLabel: {
      type: String,
      default: 'NO_RECORD_FOUND',
    },
    /** Custom loading message */
    loadingLabel: {
      type: String,
      default: 'Loading...',
    },
    /** Table height constraint */
    tableHeight: {
      type: String,
      default: undefined,
    },
    /** CSS class for the inner q-table */
    tableClass: {
      type: String,
      default: 'dashboard-height-tabs',
    },
    /** Custom rows per page options for pagination dropdown */
    rowsPerPageOptions: {
      type: Array as PropType<number[]>,
      default: () => [10, 20, 25, 50],
    },
    /** Custom label for pagination size (translation key) */
    paginationLabel: {
      type: String,
      default: 'pagination_size',
    },
    /** Settings key for persisting pagination size in user preferences */
    paginationSettingsKey: {
      type: String,
      default: '',
    },
    /** Enable/disable table features */
    features: {
      type: Object as PropType<Partial<TableFeatures>>,
      default: () => ({
        sorting: true,
        filtering: true,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: true,
        pagination: false,
        columnReorder: false,
      }),
    },
    /** Combined sort and pagination state */
    pagination: {
      type: Object as PropType<TablePaginationState>,
      default: () => ({
        sortBy: null,
        descending: true,
        page: 1,
        rowsPerPage: 50,
        rowsNumber: 0,
      }),
    },
    /** Array of selected row IDs (controlled mode) */
    selectedRows: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
    /** ID for column resize persistence in LocalStorage */
    tableId: {
      type: String,
      default: undefined,
    },
    /** Initial column order (array of column names, for persistence) */
    columnOrder: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
  },
  emits: [
    'update:sorting',
    'update:pagination',
    'update:filters',
    'selection-change',
    'bulk-action',
    'row-action',
    'row-click',
    'column-reorder',
    'group-prefetch',
    'group-prefetch-cancel',
  ],
  setup(props, { emit }) {
    const { t } = useTranslate();
    const dashboardStore = useDashboardStore();

    // Refs
    const tableRef = ref<InstanceType<typeof QTable>>();
    const tableWrapperRef = ref<HTMLElement>();
    const selectedRowsSet = ref<Set<string>>(new Set(props.selectedRows || []));
    // Row-ids whose full-width detail row (`row-detail` slot) is open — only
    // used when features.expandable is set (toggled by row click).
    const expandedRowsSet = ref<Set<string>>(new Set());
    const hasLoadedOnce = ref(false);
    const columnOrderState = ref<string[]>([]);

    // Internal sort state for client-side sorting
    const internalSortBy = ref<string | null>(null);
    const internalSortDescending = ref(false);

    // Internal pagination state for client-side pagination
    const internalPage = ref(1);
    const internalPageSize = ref(50);

    // Computed for composables (need to be defined in setup for reactivity)
    const preventDragColumnNames = computed(() => {
      const names = ['__actions__'];
      // Access features and displayColumns through closure
      return names;
    });

    const resizableEnabled = computed(() => props.features?.resizable ?? false);

    // Drag-drop composable (stays in setup)
    const dragDrop = useDragDropColumn({
      tableId: props.tableId || 'docbits-table',
      preventDragColumns: preventDragColumnNames,
      onColumnDrop: (columns: any[]) => {
        const newOrder = columns.map(c => c.name).filter(name => name !== '__actions__');
        columnOrderState.value = newOrder;
        // Emit the column-reorder event to parent (only on drop, not during drag)
        emit('column-reorder', newOrder);
      },
      onColumnSwap: (columns: any[]) => {
        // Only update local state during drag - don't emit event yet
        const newOrder = columns.map(c => c.name).filter(name => name !== '__actions__');
        columnOrderState.value = newOrder;
      },
      onDragStart: () => dashboardStore.setDraggingColumn(true),
      onDragEnd: () => dashboardStore.setDraggingColumn(false),
    });

    // Resizable table composable (stays in setup)
    useTableResizable({
      tableRef: tableWrapperRef,
      tableId: props.tableId || 'docbits-table',
      enabled: resizableEnabled,
    });

    // Column filter composable
    // Note: Column header filters are always client-side only
    // Filters are persisted to localStorage using tableId as key
    const columnsRef = computed(() => props.columns);
    const columnFilter = useColumnFilter({
      columns: columnsRef,
      storageKey: props.tableId,
    });

    return {
      t,
      dashboardStore,
      tableRef,
      tableWrapperRef,
      selectedRowsSet,
      expandedRowsSet,
      hasLoadedOnce,
      columnOrderState,
      dragDrop,
      internalSortBy,
      internalSortDescending,
      internalPage,
      internalPageSize,
      columnFilter,
    };
  },
  computed: {
    // Feature flags computed
    featuresComputed(): Required<TableFeatures> {
      return {
        sorting: this.features?.sorting ?? true,
        filtering: this.features?.filtering ?? true,
        selection: this.features?.selection ?? false,
        bulkActions: this.features?.bulkActions ?? false,
        rowActions: this.features?.rowActions ?? false,
        resizable: this.features?.resizable ?? false,
        pagination: this.features?.pagination ?? false,
        columnReorder: this.features?.columnReorder ?? false,
        columnSettings: this.features?.columnSettings ?? false,
        stickyFirstColumn: this.features?.stickyFirstColumn ?? false,
        stickyLastColumn: this.features?.stickyLastColumn ?? false,
        clientSideSort: this.features?.clientSideSort ?? false,
        clientSideFilter: this.features?.clientSideFilter ?? false,
        clientSidePagination: this.features?.clientSidePagination ?? false,
        expandable: this.features?.expandable ?? false,
      };
    },
    // Filtered and sorted rows for client-side operations
    sortedRows(): any[] {
      if (!Array.isArray(this.rows)) {
        console.warn('[DocBitsTable] rows prop is not an array — received:', typeof this.rows);
        return [];
      }
      let result: any[] = this.rows;

      // Column header filters always apply client-side filtering
      if (this.featuresComputed.filtering && this.columnFilter.hasActiveFilters.value) {
        result = this.columnFilter.filterRows(result);
      }

      // Apply client-side sorting if enabled
      if (this.featuresComputed.clientSideSort && this.internalSortBy) {
        const sortColName = this.internalSortBy as string;
        const colDef = this.columns.find((c: any) => c.name === sortColName);
        const sorted = [...result].sort((a: any, b: any) => {
          let aVal: any;
          let bVal: any;
          if (colDef && typeof colDef.field === 'function') {
            aVal = colDef.field(a);
            bVal = colDef.field(b);
          } else {
            const field = (colDef?.field as string) || sortColName;
            aVal = a[field];
            bVal = b[field];
          }

          // Handle null/undefined values
          if (aVal == null) aVal = '';
          if (bVal == null) bVal = '';

          // String comparison
          if (typeof aVal === 'string' && typeof bVal === 'string') {
            return aVal.localeCompare(bVal);
          }

          // Number comparison
          if (aVal < bVal) return -1;
          if (aVal > bVal) return 1;
          return 0;
        });

        result = this.internalSortDescending ? sorted.reverse() : sorted;
      }

      return result;
    },
    // Total row count after filtering (for client-side pagination)
    filteredRowCount(): number {
      return this.sortedRows.length;
    },
    // Effective page (internal or from prop)
    effectivePage(): number {
      if (this.featuresComputed.clientSidePagination) {
        return this.internalPage;
      }
      return this.pagination?.page ?? 1;
    },
    // Effective page size (internal or from prop)
    effectivePageSize(): number {
      if (this.featuresComputed.clientSidePagination) {
        return this.internalPageSize;
      }
      return this.pagination?.rowsPerPage ?? 50;
    },
    // Paginated rows for display
    paginatedRows(): any[] {
      if (!this.featuresComputed.clientSidePagination) {
        return this.sortedRows;
      }

      const page = this.effectivePage;
      const pageSize = this.effectivePageSize;
      const startIndex = (page - 1) * pageSize;
      const endIndex = startIndex + pageSize;

      return this.sortedRows.slice(startIndex, endIndex);
    },
    // Total pages from filtered data
    totalPagesComputed(): number {
      if (this.featuresComputed.clientSidePagination) {
        const rowCount = this.filteredRowCount;
        const pageSize = this.effectivePageSize;
        if (pageSize <= 0 || rowCount <= 0) return 1;
        return Math.ceil(rowCount / pageSize);
      }
      // Server-side: use existing logic
      const rowsNumber = this.pagination?.rowsNumber ?? 0;
      const rowsPerPage = this.pagination?.rowsPerPage ?? 50;
      if (rowsPerPage <= 0 || rowsNumber <= 0) return 1;
      return Math.ceil(rowsNumber / rowsPerPage);
    },
    // Total matching records — filtered count for client-side, rowsNumber for server-side
    totalRowsCount(): number {
      if (this.featuresComputed.clientSidePagination) {
        return this.filteredRowCount;
      }
      return this.pagination?.rowsNumber ?? 0;
    },
    // Effective sort state (internal or from pagination prop)
    effectiveSortBy(): string | null {
      if (this.featuresComputed.clientSideSort) {
        return this.internalSortBy;
      }
      return this.pagination?.sortBy ?? null;
    },
    effectiveSortDescending(): boolean {
      if (this.featuresComputed.clientSideSort) {
        return this.internalSortDescending;
      }
      return this.pagination?.descending ?? false;
    },
    rowActionsComputed(): RowActionItem[] {
      return this.rowActions || [];
    },
    // Visible columns
    visibleColumns(): string[] {
      const cols = this.columns.map((col) => col.name);
      if (this.featuresComputed?.rowActions && this.rowActionsComputed.length > 0) {
        cols.push('__actions__');
      }
      return cols;
    },
    // Display columns
    displayColumns(): (UnifiedTableColumn & { canSort?: boolean })[] {
      const visibleSet = new Set(this.visibleColumns);

      let cols = this.columns
        .filter((col) => visibleSet.has(col.name))
        .map(col => ({
          ...col,
          canSort: col.sortable !== false && col.name != 'actions',
          sortable: false,
        }));

      if (this.featuresComputed.columnReorder && this.columnOrderState.length > 0) {
        const orderMap = new Map<string, number>(this.columnOrderState.map((name, index) => [name, index]));
        cols = cols.sort((a, b) => {
          const aPos: number = orderMap.get(a.name) ?? Infinity;
          const bPos: number = orderMap.get(b.name) ?? Infinity;
          return aPos - bPos;
        });
      }

      if (this.featuresComputed.rowActions && this.rowActionsComputed.length > 0) {
        cols.push({
          name: '__actions__',
          label: 'Actions',
          field: '__actions__',
          align: 'right',
          sortable: false,
          canSort: false,
        });
      }

      return cols;
    },
    // Selection computed
    selectedCount(): number {
      return this.selectedRowsSet.size;
    },
    selectableDataRows(): any[] {
      return this.rows.filter((row) => !this.isGroupRow(row));
    },
    allRowsSelected(): boolean {
      return (
        this.selectableDataRows.length > 0
        && this.selectedRowsSet.size === this.selectableDataRows.length
      );
    },
    someRowsSelected(): boolean {
      return (
        this.selectedRowsSet.size > 0
        && this.selectedRowsSet.size < this.selectableDataRows.length
      );
    },
    // Pagination computed
    paginationSizeLabel(): string {
      return this.$t(this.paginationLabel || 'pagination_size');
    },
    currentPageSize(): string {
      return String(this.effectivePageSize);
    },
    pageSizeOptionsStrings(): string[] {
      return (this.rowsPerPageOptions || [10, 20, 25, 50]).map(String);
    },
    currentPage(): number {
      return this.effectivePage;
    },
    skeletonRowCount(): number {
      const pageSize = this.pagination?.rowsPerPage ?? 10;
      return Math.min(pageSize, 20);
    },
    totalPages(): number {
      return this.totalPagesComputed;
    },
    // Styling computed
    tableClasses(): Record<string, boolean> {
      return {
        'dense-mode': this.dense,
        'flat-style': this.flatStyle,
        'striped-mode': this.striped,
        'sticky-first-column': this.featuresComputed.stickyFirstColumn,
        'sticky-last-column': this.featuresComputed.stickyLastColumn,
      };
    },
    containerClasses(): Record<string, boolean> {
      return {
        'dark-mode': this.dark,
      };
    },
    containerStyle(): Record<string, string> {
      if (!this.tableHeight) return {};
      return {
        height: this.tableHeight,
        maxHeight: this.tableHeight,
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
      };
    },
    // Pagination sync
    paginationSync: {
      get(): TablePaginationState {
        return {
          sortBy: this.pagination?.sortBy || undefined,
          descending: this.pagination?.descending ?? true,
          page: this.pagination?.page ?? 1,
          rowsPerPage: this.pagination?.rowsPerPage ?? 50,
          rowsNumber: this.pagination?.rowsNumber ?? 0,
        };
      },
      set(newVal: TablePaginationState): void {
        if (
          newVal.page !== this.pagination?.page ||
          newVal.rowsPerPage !== this.pagination?.rowsPerPage
        ) {
          this.emitPagination(newVal.page, newVal.rowsPerPage);
        }
      },
    },
    // Drag-drop computed
    preventDragColumnNames(): string[] {
      const names = ['__actions__'];
      if (this.featuresComputed.stickyLastColumn && this.displayColumns.length > 0) {
        const lastColName = this.displayColumns[this.displayColumns.length - 1]?.name;
        if (lastColName && !names.includes(lastColName)) {
          names.push(lastColName);
        }
      }
      for (const col of this.columns) {
        if (col.draggable === false && !names.includes(col.name)) {
          names.push(col.name);
        }
      }
      return names;
    },
  },
  mounted(): void {
    if (!this.loading) {
      this.hasLoadedOnce = true;
    }
  },
  watch: {
    loading: {
      handler(isLoading: boolean, wasLoading: boolean): void {
        if (wasLoading === true && isLoading === false) {
          this.hasLoadedOnce = true;
        }
        if (!isLoading && this.rows.length > 0) {
          this.hasLoadedOnce = true;
        }
      },
      immediate: true,
    },
    columns: {
      handler(newCols: UnifiedTableColumn[]): void {
        // Don't overwrite column order while user is dragging
        if (this.dragDrop.isDragging.value) return;

        if (this.columnOrder && this.columnOrder.length > 0) {
          this.columnOrderState = [...this.columnOrder];
        } else if (this.columnOrderState.length === 0) {
          this.columnOrderState = newCols.map(c => c.name);
        }
      },
      immediate: true,
    },
    columnOrder: {
      handler(savedOrder: string[]): void {
        // Don't overwrite column order while user is dragging
        if (this.dragDrop.isDragging.value) return;

        if (savedOrder && savedOrder.length > 0) {
          this.columnOrderState = [...savedOrder];
        }
      },
      immediate: true,
    },
    'selectedRows': {
      handler(newVal: string[]): void {
        if (newVal) {
          this.selectedRowsSet = new Set(newVal);
        }
      },
    },
    // Reset to page 1 when filters change
    'columnFilter.activeFilterCount.value': {
      handler(newCount: number, oldCount: number): void {
        if (this.featuresComputed.clientSidePagination && newCount !== oldCount) {
          this.internalPage = 1;
        }
      },
    },
    // Validate page bounds when data changes
    'filteredRowCount': {
      handler(newCount: number): void {
        if (this.featuresComputed.clientSidePagination) {
          const maxPage = Math.ceil(newCount / this.effectivePageSize) || 1;
          if (this.internalPage > maxPage) {
            this.internalPage = maxPage;
          }
        }
      },
    },
    // Initialize from pagination prop
    pagination: {
      handler(newPagination: TablePaginationState | undefined): void {
        if (this.featuresComputed.clientSidePagination && newPagination) {
          if (newPagination.page && this.internalPage === 1) {
            this.internalPage = newPagination.page;
          }
          if (newPagination.rowsPerPage && this.internalPageSize === 50) {
            this.internalPageSize = newPagination.rowsPerPage;
          }
        }
      },
      immediate: true,
    },
  },
  methods: {
    isNonDraggableColumn(colName: string): boolean {
      return this.preventDragColumnNames.includes(colName);
    },
    isGroupRow(row: any): boolean {
      return row?._is_group_row === true;
    },
    isGroupSummaryRow(row: any): boolean {
      return row?._group_summary === true;
    },
    isGroupValueCell(row: any, col: any): boolean {
      if (col?.name === row?._group_field) {
        return true;
      }

      const firstDataColumn = this.displayColumns.find(
        (column: any) => column.name !== '__actions__',
      );
      return firstDataColumn?.name === col?.name;
    },
    isGroupSummaryLabelCell(col: any): boolean {
      const firstDataColumn = this.displayColumns.find(
        (column: any) => column.name !== '__actions__',
      );
      return firstDataColumn?.name === col?.name;
    },
    groupRowCount(row: any): number {
      const candidates = [
        row?._group_count,
        row?.count,
        row?.documents,
        row?.document_count,
        row?.documents_count,
        row?.doc_count,
        row?.docs_count,
        row?.total_count,
        row?.total,
        row?._count,
        row?.Documents,
      ];
      const count = candidates
        .map((value) => Number(value))
        .find((value) => Number.isFinite(value) && value > 0);

      return count ?? 1;
    },
    groupRowLabel(row: any): string {
      const label = row?._group_label ?? row?.label ?? row?.[row?._group_field] ?? '';
      return `${label} (${this.groupRowCount(row).toLocaleString()})`;
    },
    hasGroupAggregateValue(row: any, col: any): boolean {
      const value = this.groupAggregateValue(row, col);
      return value !== undefined && value !== null && value !== '';
    },
    groupAggregateValue(row: any, col: any): unknown {
      const field = col?.name;
      if (!field || field === row?._group_field) return undefined;

      const direct = row?.[field];
      if (direct !== undefined && direct !== null && direct !== '') return direct;

      const aggregateKeys = [
        `${field}_sum`,
        `sum_${field}`,
        `${field}_total`,
        `total_${field}`,
        `${field}_avg`,
        `avg_${field}`,
        `${field}_min`,
        `min_${field}`,
        `${field}_max`,
        `max_${field}`,
      ];
      for (const key of aggregateKeys) {
        const value = row?.[key];
        if (value !== undefined && value !== null && value !== '') return value;
      }

      const nested = row?.aggregates?.[field] ?? row?.aggregate?.[field];
      if (nested && typeof nested === 'object') {
        for (const op of ['sum', 'total', 'avg', 'min', 'max', 'count']) {
          const value = nested[op];
          if (value !== undefined && value !== null && value !== '') return value;
        }
      }

      return undefined;
    },
    groupAggregateOperationLabel(row: any, col: any): string {
      const field = col?.name;
      const operation = field ? row?._group_aggregate_ops?.[field] : undefined;
      if (operation === 'count') return 'Count';
      if (operation === 'avg') return 'Avg';
      if (operation === 'min') return 'Min';
      if (operation === 'max') return 'Max';
      return 'Σ Sum';
    },
    isCurrencyColumn(field: unknown): boolean {
      return /(^|_)(amount|balance|price|tax|total|value)s?$/.test(String(field || '').toLowerCase());
    },
    formatGroupAggregateValue(value: unknown, col?: any): string {
      if (typeof value === 'number' && Number.isFinite(value)) {
        if (this.isCurrencyColumn(col?.name)) {
          return value.toLocaleString(undefined, {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          });
        }
        return value.toLocaleString();
      }
      return String(value ?? '-');
    },
    handleGroupRowToggle(event: Event, row: any, rowIndex: number): void {
      event.stopPropagation();
      this.$emit('row-click', { row, rowIndex });
    },
    handleGroupPrefetch(row: any, rowIndex: number): void {
      this.$emit('group-prefetch', { row, rowIndex });
    },
    handleGroupPrefetchCancel(row: any, rowIndex: number): void {
      this.$emit('group-prefetch-cancel', { row, rowIndex });
    },
    getColumnIndex(colName: string): number {
      return this.displayColumns.findIndex(c => c.name === colName);
    },
    handleColumnSort(payload: { column: string; direction: 'asc' | 'desc' | null }): void {
      if (this.featuresComputed.clientSideSort) {
        if (payload.direction === null) {
          // Clear sort — revert to original order
          this.internalSortBy = null;
          this.internalSortDescending = false;
        } else {
          this.internalSortBy = payload.column;
          this.internalSortDescending = payload.direction === 'desc';
        }
      }
      this.$emit('update:sorting', payload as SortEventPayload);
    },
    // Single coercion chokepoint for every update:pagination emit. Consumers
    // write these values straight into their stores / offset math, so a
    // NaN/0/undefined page or rowsPerPage here poisons page_size -> skip=NaN ->
    // HTTP 422 / "NaN / NaN" on EVERY table page, not just one. DOCB-12859.
    emitPagination(page: unknown, rowsPerPage: unknown): void {
      this.$emit('update:pagination', {
        page: toPositiveInt(page, 1),
        rowsPerPage: toPositiveInt(rowsPerPage, this.effectivePageSize || 50),
      });
    },
    handlePageSizeChange(newSize: string): void {
      const size = Number(newSize);

      if (this.featuresComputed.clientSidePagination) {
        this.internalPageSize = size;
        this.internalPage = 1;
      }

      this.emitPagination(1, size);
    },
    handlePageChange(newPage: number): void {
      if (this.featuresComputed.clientSidePagination) {
        this.internalPage = newPage;
      }

      this.emitPagination(newPage, this.effectivePageSize);
    },
    handleRowAction(actionKey: string, row: any): void {
      this.$emit('row-action', {
        action: actionKey,
        rowId: String(row[this.rowKey]),
        row,
      });
    },
    handleMasterToggle(selectAll: boolean): void {
      if (!Array.isArray(this.rows)) return;
      if (selectAll) {
        const validIds = this.rows
          .filter((row) => !this.isGroupRow(row) && !this.isGroupSummaryRow(row))
          .map((r) => r[this.rowKey])
          .filter((id) => id !== undefined && id !== null && String(id).trim() !== '');
        this.selectedRowsSet = new Set(validIds.map(String));
      } else {
        this.selectedRowsSet.clear();
      }
      this.emitSelectionChange();
    },
    handleRowToggle(rowId: string, isSelected: boolean): void {
      if (
        rowId === undefined ||
        rowId === null ||
        rowId === 'undefined' ||
        rowId === 'null' ||
        String(rowId).trim() === ''
      ) {
        return;
      }

      if (isSelected) {
        this.selectedRowsSet.add(rowId);
      } else {
        this.selectedRowsSet.delete(rowId);
      }
      this.emitSelectionChange();
    },
    handleRowClick(event: Event, row: any, rowIndex: number): void {
      if (this.isGroupSummaryRow(row)) return;
      if (this.selectOnRowClick && this.featuresComputed.selection && !this.isGroupRow(row)) {
        this.handleRowToggle(String(row[this.rowKey]), !this.selectedRowsSet.has(String(row[this.rowKey])));
      }
      if (this.featuresComputed.expandable && !this.isGroupRow(row)) {
        const rowId = String(row[this.rowKey]);
        // Mutate via a fresh Set so Vue reactivity picks up the change.
        const next = new Set(this.expandedRowsSet);
        if (next.has(rowId)) {
          next.delete(rowId);
        } else {
          next.add(rowId);
        }
        this.expandedRowsSet = next;
      }
      this.$emit('row-click', { row, rowIndex });
    },
    onTableRequest(requestProps: any): void {
      if (this.featuresComputed.pagination) {
        this.emitPagination(
          requestProps.pagination.page,
          requestProps.pagination.rowsPerPage,
        );
      }
    },
    handleBulkExport(): void {
      this.$emit('bulk-action', {
        action: 'export',
        selectedIds: Array.from(this.selectedRowsSet),
        selectedCount: this.selectedCount,
      });
    },
    handleBulkDelete(): void {
      this.$emit('bulk-action', {
        action: 'delete',
        selectedIds: Array.from(this.selectedRowsSet),
        selectedCount: this.selectedCount,
      });
    },
    handleBulkCopyIds(): void {
      this.$emit('bulk-action', {
        action: 'copy-ids',
        selectedIds: Array.from(this.selectedRowsSet),
        selectedCount: this.selectedCount,
      });
    },
    handleClearSelection(): void {
      this.selectedRowsSet.clear();
      this.emitSelectionChange();
    },
    emitSelectionChange(): void {
      const selectedRowIds = Array.from(this.selectedRowsSet);
      const safeRows = Array.isArray(this.rows) ? this.rows : [];
      const selectedRowObjects = safeRows.filter((r) =>
        this.selectedRowsSet.has(r[this.rowKey])
      );

      this.$emit('selection-change', {
        selectedIds: selectedRowIds,
        selectedRows: selectedRowObjects,
        totalSelected: this.selectedCount,
        totalAvailable: safeRows.length,
      });
    },
    handleColumnDrop(columns: any[]): void {
      const newOrder = columns.map(c => c.name).filter(name => name !== '__actions__');
      this.columnOrderState = newOrder;
      this.$emit('column-reorder', newOrder);
    },
    // Filter methods
    isColumnFilterable(col: UnifiedTableColumn): boolean {
      return this.columnFilter.isFilterable(col);
    },
    getColumnFilterType(col: UnifiedTableColumn): 'text' | 'date' | 'number' | 'select' {
      return this.columnFilter.getColumnFilterType(col);
    },
    getColumnFilterOperators(col: UnifiedTableColumn): Array<{ label: string; value: FilterOperator }> {
      return this.columnFilter.getColumnOperators(col);
    },
    getColumnFilterOptions(col: UnifiedTableColumn): Array<{ label: string; value: string | number }> {
      const config = this.columnFilter.getColumnFilterConfig(col);
      return config?.options || [];
    },
    handleFilterUpdate(payload: { column: string; value: string | number; operator: FilterOperator }): void {
      this.columnFilter.setFilter(payload.column, payload.value, payload.operator);
      this.$emit('update:filters', {
        action: 'set',
        column: payload.column,
        value: payload.value,
        operator: payload.operator,
        filters: this.columnFilter.activeFilters.value,
      });
    },
    handleFilterClear(column: string): void {
      this.columnFilter.clearFilter(column);
      this.$emit('update:filters', {
        action: 'clear',
        column,
        filters: this.columnFilter.activeFilters.value,
      });
    },
    handleClearAllFilters(): void {
      this.columnFilter.clearAllFilters();
      this.$emit('update:filters', {
        action: 'clear-all',
        filters: [],
      });
    },
  },
});
</script>

