import { ref, Ref, onBeforeUnmount, unref, ComputedRef } from 'vue';
import { useTranslate } from '@tolgee/vue';

export interface DragDropColumnOptions {
  /** The table element ID */
  tableId: string;
  /** Key in column object to use for drag label (default: 'label') */
  labelKey?: string;
  /** Column names that should not be draggable (can be reactive) */
  preventDragColumns?: string[] | Ref<string[]> | ComputedRef<string[]>;
  /** Callback when columns are reordered (on drop) */
  onColumnDrop?: (columns: any[], isFromSort: boolean) => void;
  /** Callback when columns are swapped during drag (for live preview) */
  onColumnSwap?: (columns: any[]) => void;
  /** Callback when column drag starts (use to update global drag state) */
  onDragStart?: () => void;
  /** Callback when column drag ends (use to update global drag state) */
  onDragEnd?: () => void;
}

export interface DragDropColumnReturn {
  /** Whether a column is currently being dragged */
  isDragging: Ref<boolean>;
  /** Initialize drag-drop for the table */
  init: () => void;
  /** Cleanup drag-drop handlers */
  cleanup: () => void;
  /** Check if a column can be dragged */
  canDragColumn: (column: any) => boolean;
  /** Handle drag start on a column header */
  onDragStart: (event: DragEvent, columns: any[], columnIndex: number) => void;
  /** Handle drag over a column header */
  onDragOver: (event: DragEvent, columnIndex: number) => void;
  /** Handle drop on a column header */
  onDrop: (event: DragEvent, columnIndex: number) => void;
}

const COLUMN_SWAP_DEBOUNCE_MS = 16;

function debounce<T extends (...args: any[]) => void>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  return (...args: Parameters<T>) => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      fn(...args);
      timeoutId = null;
    }, delay);
  };
}

/**
 * Composable for handling drag-drop column reordering in tables
 * Converted from dragDropColumn.js mixin to Composition API
 */
export function useDragDropColumn(options: DragDropColumnOptions): DragDropColumnReturn {
  const { t } = useTranslate();

  const {
    tableId,
    labelKey = 'label',
    preventDragColumns = [],
    onColumnDrop,
    onColumnSwap,
    onDragStart: onDragStartCallback,
    onDragEnd: onDragEndCallback,
  } = options;

  const isDragging = ref(false);
  const isColumnDragging = ref(false);

  let tableColumns: any[] = [];
  let tableColumnsOriginal = '';
  let indexToMove = -1;
  let oldIndex = -1;
  let lastSwappedIndex = -1;
  let lastX = -1;
  let tableScrollInterval: ReturnType<typeof setInterval> | null = null;
  let draggingLabel = '';

  const debouncedColumnSwap = onColumnSwap
    ? debounce((columns: any[]) => onColumnSwap(columns), COLUMN_SWAP_DEBOUNCE_MS)
    : null;

  /**
   * Check if a column can be dragged
   * Uses unref to support both static arrays and reactive refs
   */
  function canDragColumn(column: any): boolean {
    if (!column) return false;
    const preventList = unref(preventDragColumns);
    return !preventList.includes(column.name);
  }

  function generateScrollDiv() {
    const table = document.getElementById(tableId);
    if (!table) return;

    const scrollLeft = document.createElement('div');
    scrollLeft.classList.add('table-scroll-area-left');
    scrollLeft.id = tableId + '-scroll-left';

    const scrollRight = document.createElement('div');
    scrollRight.classList.add('table-scroll-area-right');
    scrollRight.id = tableId + '-scroll-right';

    scrollLeft.addEventListener('dragenter', (e) => {
      e.preventDefault();
      scrollDragEnter(-2);
    });
    scrollLeft.addEventListener('dragleave', (e) => {
      e.preventDefault();
      scrollDragLeave();
    });

    scrollRight.addEventListener('dragenter', (e) => {
      e.preventDefault();
      scrollDragEnter(2);
    });
    scrollRight.addEventListener('dragleave', (e) => {
      e.preventDefault();
      scrollDragLeave();
    });

    table.append(scrollLeft);
    table.append(scrollRight);
  }

  function removeScrollDiv() {
    const scrollRight = document.getElementById(tableId + '-scroll-right');
    const scrollLeft = document.getElementById(tableId + '-scroll-left');
    scrollRight?.remove();
    scrollLeft?.remove();
  }

  function scrollDragEnter(speed: number) {
    tableScrollInterval = setInterval(() => {
      const content = document.getElementById(tableId)?.querySelector('div');
      if (content) {
        content.scrollLeft += speed;
      }
    }, 10);
  }

  function scrollDragLeave() {
    if (tableScrollInterval) {
      clearInterval(tableScrollInterval);
      tableScrollInterval = null;
    }
  }

  function onDragStart(event: DragEvent, columns: any[], columnIndex: number) {
    if (!event.dataTransfer) return;

    // Prevent dragging non-draggable columns (like sticky __actions__)
    if (!canDragColumn(columns[columnIndex])) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    // Check if clicking on resize handle (use elementFromPoint since event.target is the th)
    const elementAtPoint = document.elementFromPoint(event.clientX, event.clientY) as HTMLElement;
    const target = event.target as HTMLElement;
    const isResizeHandle = elementAtPoint?.hasAttribute('data-resize-handle') ||
                           elementAtPoint?.closest('[data-resize-handle]') ||
                           elementAtPoint?.style?.cursor === 'col-resize' ||
                           target?.hasAttribute('data-resize-handle') ||
                           target?.closest('[data-resize-handle]') ||
                           target?.style?.cursor === 'col-resize';
    if (isResizeHandle) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    isColumnDragging.value = true;
    isDragging.value = true;

    if (onDragStartCallback) {
      onDragStartCallback();
    }

    tableColumnsOriginal = JSON.stringify(columns);
    tableColumns = columns;
    indexToMove = columnIndex;
    oldIndex = columnIndex;
    event.dataTransfer.effectAllowed = 'move';
    (event.currentTarget as HTMLElement)?.classList.add('dragging-column');

    event.dataTransfer.setData(
      'text/plain',
      JSON.stringify({
        tableColumns: tableColumns,
        indexToMove: indexToMove,
        tableId: tableId,
      })
    );

    localStorage.setItem('dragInfo', JSON.stringify({ tableId: tableId }));
    document.documentElement.classList.add('draggable-cursor');

    const ghostElement = document.createElement('div');
    ghostElement.id = 'ghost-element';
    ghostElement.classList.add('font-size-14');
    document.body.classList.add('overflow-hidden');
    ghostElement.style.cursor = 'move';

    if (!draggingLabel) {
      const column = tableColumns[indexToMove];
      const label = column[labelKey];
      if (label) {
        try {
          draggingLabel = t.value(label);
        } catch {
          draggingLabel = label;
        }
      }
    }

    const iconSpan = document.createElement('span');
    iconSpan.className = 'material-icons';
    iconSpan.style.fontSize = '18px';
    iconSpan.textContent = 'drag_indicator';
    ghostElement.appendChild(iconSpan);
    ghostElement.appendChild(document.createTextNode(draggingLabel));
    document.body.appendChild(ghostElement);
    event.dataTransfer.setDragImage(ghostElement, 70, 30);

    setTimeout(() => {
      document.body.removeChild(ghostElement);
      document.body.classList.remove('overflow-hidden');
      generateScrollDiv();
    }, 1);

    window.addEventListener('dragend', onDragEnd);
  }

  function onDragEnd(event: DragEvent) {
    if (indexToMove === null || indexToMove === undefined || indexToMove === -1) return;

    scrollDragLeave();
    localStorage.removeItem('dragInfo');
    isColumnDragging.value = false;

    if (onDragEndCallback) {
      onDragEndCallback();
    }

    window.removeEventListener('dragend', onDragEnd);

    const columnToMove = tableColumns[indexToMove];
    if (!columnToMove) return;

    document.documentElement.classList.remove('draggable-cursor');
    document.querySelector('.dragging-column')?.classList.remove('dragging-column');
    isDragging.value = false;

    if (tableColumnsOriginal !== JSON.stringify(tableColumns)) {
      if (onColumnDrop) {
        onColumnDrop(tableColumns, true);
      }

      const customEvent = new CustomEvent(tableId + '-column-drop', {
        detail: { tableColumns: tableColumns, isFromSort: true },
      });
      document.dispatchEvent(customEvent);
    }

    lastSwappedIndex = -1;
    indexToMove = -1;
    draggingLabel = '';
    removeScrollDiv();
  }

  function onDragOver(event: DragEvent, columnIndex: number) {
    if (!isColumnDragging.value) {
      return;
    }

    // Prevent dragging over non-draggable columns (like sticky __actions__)
    if (!canDragColumn(tableColumns[columnIndex])) {
      event.preventDefault();
      event.dataTransfer!.dropEffect = 'none';
      return;
    }

    // Prevent dragging past the last draggable column
    // Find the index of the first non-draggable column
    const firstNonDraggableIndex = tableColumns.findIndex(col => !canDragColumn(col));
    if (firstNonDraggableIndex !== -1 && columnIndex >= firstNonDraggableIndex) {
      event.preventDefault();
      event.dataTransfer!.dropEffect = 'none';
      return;
    }

    const dragInfoStr = localStorage.getItem('dragInfo');
    if (dragInfoStr) {
      const dragInfo = JSON.parse(dragInfoStr);
      const table = (event.target as HTMLElement).closest('.q-table__container');
      if (table && table.id !== dragInfo.tableId) {
        return;
      }
    } else {
      return;
    }

    event.preventDefault();
    event.dataTransfer!.effectAllowed = 'move';
    event.dataTransfer!.dropEffect = 'move';
    document.documentElement.classList.remove('draggable-cursor');

    if (lastX === event.clientX) return;
    if (lastSwappedIndex > -1) {
      const countDifferent = lastSwappedIndex - columnIndex;
      if (countDifferent === -1 && lastX > event.clientX) {
        lastX = event.clientX;
        return;
      }
      if (countDifferent === 1 && lastX < event.clientX) {
        lastX = event.clientX;
        return;
      }
    }

    if (columnIndex === indexToMove) {
      return;
    }

    const columnToMove = tableColumns[indexToMove];
    tableColumns.splice(indexToMove, 1);
    tableColumns.splice(columnIndex, 0, columnToMove);

    if (debouncedColumnSwap) {
      debouncedColumnSwap([...tableColumns]);
    }

    indexToMove = columnIndex;
    lastSwappedIndex = columnIndex;
    lastX = event.clientX;
  }

  function onDrop(event: DragEvent, columnIndex: number) {
    scrollDragLeave();
    document.documentElement.classList.remove('draggable-column');

    // Prevent drops on non-draggable columns
    if (!canDragColumn(tableColumns[columnIndex])) {
      event.preventDefault();
      return;
    }

    // Prevent drops past the first non-draggable column
    const firstNonDraggableIndex = tableColumns.findIndex(col => !canDragColumn(col));
    if (firstNonDraggableIndex !== -1 && columnIndex >= firstNonDraggableIndex) {
      event.preventDefault();
      return;
    }
  }

  function init() {}

  function cleanup() {
    scrollDragLeave();
    removeScrollDiv();
    localStorage.removeItem('dragInfo');
    window.removeEventListener('dragend', onDragEnd);
    document.documentElement.classList.remove('draggable-cursor');

    if (isColumnDragging.value && onDragEndCallback) {
      onDragEndCallback();
    }

    isColumnDragging.value = false;
    isDragging.value = false;
  }

  onBeforeUnmount(() => {
    cleanup();
  });

  return {
    isDragging,
    init,
    cleanup,
    canDragColumn,
    onDragStart,
    onDragOver,
    onDrop,
  };
}
